import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import type { Readiness } from './pages/Roadmap'

// public/readiness.json is generated by tools/update_roadmap.py (tools/readiness.py builds it from the real files). The page renders it as is,
// so this checks the shape the page relies on and that every state agrees with its own conditions.
const file = join(__dirname, '..', 'public', 'readiness.json')
const STATES = ['not started', 'in progress', 'ready for a first audience']

describe.skipIf(!existsSync(file))('readiness.json', () => {
  const r: Readiness = JSON.parse(readFileSync(file, 'utf-8'))
  it('has the six named areas, each with evidence', () => {
    expect(r.areas.map(a => a.name)).toEqual(['Beginner journey', 'Core lesson quality', 'Independent assessment', 'Game integration', 'Accessibility', 'Reliability'])
    for (const a of r.areas) { expect(STATES).toContain(a.state); expect(a.evidence.length).toBeGreaterThan(0) }
  })
  it('is ready exactly when every condition is met, and names the next condition otherwise', () => {
    for (const a of r.areas) {
      const allMet = a.conditions.every(c => c.met)
      expect(a.state === 'ready for a first audience').toBe(allMet)
      expect(a.next === null).toBe(allMet)
    }
    expect(r.summary).toEqual({ ready: r.areas.filter(a => a.state === 'ready for a first audience').length, total: r.areas.length })
  })
  it('lists every area that is not ready under experimental', () => {
    expect(r.experimental.length).toBe(r.summary.total - r.summary.ready)
  })
})
